import subprocess
def run(args):
    p=subprocess.run(["./executable"]+args, capture_output=True, text=True, timeout=3)
    return p.stdout.rstrip("\n"), p.stderr.strip(), p.returncode

for base in ["2","10","16"]:
    for val in ["0","1","10","100","1000","1234567","123456789"]:
        o,e,c=run(["-b",base,val])
        print(f"b{base} {val} len={len(o)} {o!r}")
    print()
for fix in ["1","2","5","10"]:
    for base in ["2","3","10"]:
        o,e,c=run(["-f",fix,"-b",base,"10.5"])
        print(f"fix{fix} b{base} 10.5 => {o!r}")
    print()
# negative large decimal
for val in ["--","-12345"]:
    pass
for val in ["-12345","-1000","-100"]:
    o,e,c=run(["--",val])
    print(f"dec {val} => {o!r}")
    o,e,c=run(["-b","2","--",val])
    print(f" b2 {val} => {o!r}")
PY"}

