import math
def to_digits(n, radix, width):
    chars="0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    s=""
    n=int(n)
    for i in range(width):
        s=chars[n%radix]+s
        n//=radix
    return s

def cand(frac_input, radix, fix, mode):
    f=frac_input
    if mode=="scaled_floor":
        scaled=math.floor(f * (radix**fix))
        return to_digits(scaled,radix,fix)
    if mode=="scaled_round":
        scaled=round(f * (radix**fix))
        return to_digits(scaled,radix,fix)
    if mode=="scaled_trunc_int":
        scaled=int(f * float(radix**fix))
        return to_digits(scaled,radix,fix)

