def _div(a, b):
    # Rust f64 division semantics
    if b == 0.0:
        if a == 0.0 or math.isnan(a):
            return math.nan
        # sign of inf = sign(a) * sign(b)
        sign = math.copysign(1.0, a) * math.copysign(1.0, b)
        return math.copysign(math.inf, sign)
    return a / b

def _pow(a, b):
    # Rust f64::powf semantics (C pow)
    if b == 0.0:
        return 1.0
    if math.isnan(a) or math.isnan(b):
        return math.nan
    # Use math.pow and translate errors
    try:
        return math.pow(a, b)
    except OverflowError:
        # C pow returns +/- inf
        neg = False
        if a < 0 and float(b).is_integer() and int(b) % 2 != 0:
            neg = True
        return -math.inf if neg else math.inf
    except ValueError:
        # 0 ** negative -> inf in C, negative ** fractional -> nan
        if a == 0.0:
