# ---------- Paths ----------
def home_dir():
    h=os.environ.get("HOME")
    if h:
        return h
    # fallback to passwd
    try:
        import pwd
        return pwd.getpwuid(os.getuid()).pw_dir
    except Exception:
        return ""
def data_home():
    x=os.environ.get("XDG_DATA_HOME")
    if x and os.path.isabs(x):
        return x
    return os.path.join(home_dir(), ".local", "share")
def cache_home():
    x=os.environ.get("XDG_CACHE_HOME")
    if x and os.path.isabs(x):
        return x
    return os.path.join(home_dir(), ".cache")

def rust_os_error(e):
    code=e.errno if e.errno is not None else 1
    kind_map={1:"Uncategorized",2:"NotFound",13:"PermissionDenied",21:"IsADirectory",20:"NotADirectory",17:"AlreadyExists",22:"InvalidInput",32:"BrokenPipe"}
    kind=kind_map.get(code, "Uncategorized")
    msg=os.strerror(code) if code else str(e)
    # Rust messages capitalized: "Is a directory", "Permission denied", "No such file or directory"
    # os.strerror gives same for linux
    return f'Os {{ code: {code}, kind: {kind}, message: "{msg}" }}'

def save_history_panic(e):
    pid=os.getpid()
    sys.stderr.write(f"\nthread 'main' ({pid}) panicked at src/main.rs:142:49:\ncalled `Result::unwrap()` on an `Err` value: Io({rust_os_error(e)})\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)

