    try:
        with open(history_path, "rb") as f:
            raw=f.read()
        text=raw.decode('utf-8')
        lines=text.splitlines()
        if lines and lines[0]=="#V2":
            lines=lines[1:]
        # rustyline v2 unescaping: lines ending with backslash continuation etc. Simple: handle \\ -> \? We'll keep raw lines as entries but unescape doubled backslash?
        # For entries loaded, they should be usable via up-arrow; save will re-escape. Store decoded entries:
        decoded=[]
        buf=""
        continuing=False
        for ln in lines:
            # In V2 format, a trailing '\' indicates line continuation? And '\\' is escaped backslash.
            # Simplify: if continuing, append with newline
            if continuing:
                buf+="\n"+ln
            else:
                buf=ln
            if buf.endswith("\\") and not buf.endswith("\\\\"):
                continuing=True
                buf=buf[:-1]
                continue
            continuing=False
            # unescape \\ to \
            decoded.append(buf.replace("\\\\","\\"))
        histories=decoded
    except Exception:
        load_ok=False
        histories=[]
    if not load_ok:
        sys.stdout.write("No previous history.\n")
