            prev_ans=new_prev
            # write prev file
            try:
                with open(prev_path, "w") as pf:
                    pf.write(rust_display(new_prev)+"\n")
            except OSError as e:
                # Original per-iteration behavior unknown; print like startup?
                sys.stdout.write(f"Could not write to previous_ans_path\n{rust_os_error(e)}\n"); sys.stdout.flush()
        except CalcError as e:
            sys.stdout.write(str(e)+"\n" if not str(e).endswith("\n") else str(e)+"\n" if False else str(e))
            # CalcError messages: normal messages have no trailing newline, our write above needs newline.
            # But help message already ends with a newline; println adds one more.
            # The above branch: for normal msg, we wrote str(e) without newline in conditional expression trick - fix logic below:
            # Actually to avoid complexity, we already wrote; need ensure newline:
            # We'll handle in except block restructuring - see code below.
            sys.stdout.flush()

    # The process_line except handling above is messy; redefine properly
    def process_line2(line):
        nonlocal prev_ans
        try:
            ans=evaluate(line, cfg, prev_ans)
            formatted=format_result(ans, cfg)
