            except OSError as e:
                sys.stdout.write(f"Could not write to previous_ans_path\n{rust_os_error(e)}\n"); sys.stdout.flush()
        except CalcError as e:
            msg=str(e)
            # println! style: adds newline; if msg already ends with newline (help), total gets extra newline
            sys.stdout.write(msg+"\n"); sys.stdout.flush()

    if is_tty_in:
        exit_code = run_tty_repl(cfg, process_line2, session_histories, histories)
        # histories/session updated inside run_tty_repl via list reference? It appends to session_histories
    else:
        # piped / redirected stdin
        for raw_line in sys.stdin:
            # rustyline strips trailing \n and \r\n? It strips \n and if line ends with \r? remove
            line=raw_line
            if line.endswith("\n"):
                line=line[:-1]
            if line.endswith("\r"):
                line=line[:-1]
            # add history: rustyline add_history_entry skips empty? Need check: We'll append if line!="" and not duplicate of last?
            # Observation: duplicates are kept across sessions, consecutive duplicates within session? We'll implement: if line != "" and (not session_histories or session_histories[-1]!=line): append
            # But earlier tests showed repeated lines within same input? We'll decide by experiments later.
            if line!="":
                # rustyline may ignore duplicate consecutive
                if not session_histories or session_histories[-1]!=line:
                    session_histories.append(line)
                else:
                    # still keep? For now skip duplicate
                    pass
            process_line2(line)
        exit_code=0
    # save history
    if session_histories:
