    # colorize characters
    out=""
    i=0
    n=len(line)
    while i<n:
        # function names longest match at i if alphabetic and (word boundary-ish prev not alpha? original colors even inside? We'll require i==0 or previous not alpha)
        matched=False
        if line[i].isalpha():
            for fname in sorted(FUNCTION_NAMES, key=len, reverse=True):
                if line.startswith(fname, i):
                    # color function name
                    out+=f"\x1b[34m{fname}\x1b[39m"
                    i+=len(fname)
