def run_tty_repl(cfg, process_line, session_histories, loaded_histories):
    import termios, tty
    fd=sys.stdin.fileno()
    old_settings=termios.tcgetattr(fd)
    # history navigation state
    hist_index=None  # None means current line
    saved_current=""
    def redraw(buf, cursor):
        # move to line start, clear line, print prompt + highlighted buf, position cursor
        sys.stdout.write("\r\x1b[K")
        sys.stdout.write("> "+highlight_line(buf, cfg))
        # compute cursor position: prompt 2 + cursor (characters before cursor plain length)
        # Highlight codes complicate moving: we after writing full line, move left by (len(buf)-cursor)
        if len(buf)-cursor>0:
            sys.stdout.write(f"\x1b[{len(buf)-cursor}D")
        sys.stdout.flush()
    buf=""
    cursor=0
    try:
        tty.setraw(fd)
        sys.stdout.write("> "); sys.stdout.flush()
