                        # Actually simpler: if code is digit, find final
                        final_byte=data[seq_end] if seq_end < len(data) else None
                        # Determine action based on final char and parameters
                        params=data[bidx+2:seq_end] if seq_end < len(data) else b""
                        fb=chr(final_byte) if final_byte else ""
                        if fb=='A':  # up
                            if session_histories:
                                if hist_index is None:
                                    saved_current=buf
                                    hist_index=len(session_histories)-1
                                elif hist_index>0:
                                    hist_index-=1
                                if hist_index is not None and 0 <= hist_index < len(session_histories):
                                    buf=session_histories[hist_index]; cursor=len(buf)
                                    redraw(buf,cursor)
                        elif fb=='B': # down
                            if hist_index is not None:
                                if hist_index < len(session_histories)-1:
                                    hist_index+=1
                                    buf=session_histories[hist_index]; cursor=len(buf)
                                else:
                                    hist_index=None
                                    buf=saved_current; cursor=len(buf)
                                redraw(buf,cursor)
                        elif fb=='C': # right
                            if cursor < len(buf):
                                cursor+=1; redraw(buf,cursor)
                        elif fb=='D': # left
                            if cursor>0:
                                cursor-=1; redraw(buf,cursor)
                        elif fb=='H': # home
                            cursor=0; redraw(buf,cursor)
                        elif fb=='F': # end
                            cursor=len(buf); redraw(buf,cursor)
                        elif fb=='~':
