                            if b'3' in params or params==b'3':
                                if cursor < len(buf):
                                    buf=buf[:cursor]+buf[cursor+1:]; redraw(buf,cursor)
                        bidx=seq_end+1
                        continue
                    else:
                        # Alt key or Esc alone: ignore
                        bidx+=1
                        continue
                elif b in (3,): # Ctrl-C
                    sys.stdout.write("\r\n"); sys.stdout.flush()
                    return 0
                elif b in (4,): # Ctrl-D
                    if buf=="":
                        sys.stdout.write("\r\n"); sys.stdout.flush()
                        return 0
                    else:
                        if cursor < len(buf):
                            buf=buf[:cursor]+buf[cursor+1:]
                            redraw(buf,cursor)
                        bidx+=1; continue
                elif b in (13,10): # Enter
                    sys.stdout.write("\r\n"); sys.stdout.flush()
                    line=buf
                    # restore terminal for processing? process writes plain
                    # temporarily restore cooked mode for output
                    termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)
                    # history add
                    if line!="":
                        if not session_histories or session_histories[-1]!=line:
                            session_histories.append(line)
                    process_line(line)
                    # back to raw
                    tty.setraw(fd)
                    buf=""; cursor=0; hist_index=None; saved_current=""
                    sys.stdout.write("> "); sys.stdout.flush()
                    bidx+=1; continue
                elif b in (21,): # Ctrl-U
                    buf=""; cursor=0; redraw(buf,cursor); bidx+=1; continue
                elif b in (11,): # Ctrl-K
                    buf=buf[:cursor]; redraw(buf,cursor); bidx+=1; continue
                elif b in (1,): # Ctrl-A
                    cursor=0; redraw(buf,cursor); bidx+=1; continue
                elif b in (5,): # Ctrl-E
                    cursor=len(buf); redraw(buf,cursor); bidx+=1; continue
                elif b in (12,): # Ctrl-L
                    sys.stdout.write("\x1b[2J\x1b[H"); sys.stdout.write("> "+highlight_line(buf,cfg)); sys.stdout.flush(); bidx+=1; continue
                elif b in (23,): # Ctrl-W delete word
                    if cursor>0:
                        start=cursor
                        while start>0 and buf[start-1]==' ':
                            start-=1
                        while start>0 and buf[start-1]!=' ':
                            start-=1
                        buf=buf[:start]+buf[cursor:]; cursor=start; redraw(buf,cursor)
                    bidx+=1; continue
                elif b in (26,): # Ctrl-Z - ignore (original would suspend? rustyline ignores?)
