                elif b in (127,8): # Backspace
                    if cursor>0:
                        buf=buf[:cursor-1]+buf[cursor:]; cursor-=1; redraw(buf,cursor)
                    bidx+=1; continue
                else:
                    # printable unicode: decode starting at bidx
                    # find utf8 length
                    # decode bytes incremental
                    # Use remaining bytes decode ignoring incomplete at chunk end (assume full)
                    try:
                        ch=data[bidx:].decode('utf-8')[0]
                        ch_bytes=len(ch.encode('utf-8'))
                    except:
                        bidx+=1; continue
                    if ch.isprintable():
                        buf=buf[:cursor]+ch+buf[cursor:]; cursor+=len(ch); hist_index=None
                        redraw(buf,cursor)
                    bidx+=ch_bytes
                    continue
    finally:
        try:
            termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)
        except:
            pass
    return 0

def main():
    cfg, input_val = parse_cli(sys.argv[1:])
    if input_val is not None and input_val!="":
        # command mode
        try:
            ans=evaluate(input_val, cfg, 0.0)
            formatted=format_result(ans, cfg)
            sys.stdout.write(formatted+"\n")
            return 0
        except CalcError as e:
            msg=str(e)
            sys.stderr.write(msg+"\n")
            return 1
    else:
        return repl(cfg)

if __name__=="__main__":
    try:
        code=main()
    except BrokenPipeError:
        code=0
    sys.exit(code)
