def build_usage(used_options, suggested=None, positional_filled=False, generic=False):
    prog=prog_name()
    if generic:
        return f"Usage: {prog} [OPTIONS] [INPUT]"
    parts=[]
    # used options in canonical order fix, base, angle_unit, help, version ?
    order=["fix","base","angle_unit","help","version"]
    included=[]
    for name in order:
        if name in used_options:
            included.append(name)
    if suggested and suggested not in included:
        # insert according to order
        included.append(suggested)
        included.sort(key=lambda n: order.index(n) if n in order else 99)
    if not included and not positional_filled:
        return f"Usage: {prog} [OPTIONS] [INPUT]"
    usage_parts=[]
    for name in included:
        usage_parts.append(LONG_OPTS[name][0])
    inp = "<INPUT>" if positional_filled else "[INPUT]"
    if usage_parts:
        return f"Usage: {prog} " + " ".join(usage_parts) + f" {inp}"
    else:
        # only positional filled
        return f"Usage: {prog} {inp}"

def format_cli_error(kind, **kw):
    # returns plain stderr text
    prog=prog_name()
    if kind=="unexpected_arg":
        arg=kw["arg"]  # display name
        original=kw.get("original", arg)
        suggested=kw.get("suggested")  # long name key
        used=kw.get("used", set())
        positional_filled=kw.get("positional_filled", False)
        is_positional=kw.get("is_positional", False)
        is_short=kw.get("is_short", False)
        if is_positional:
            usage=build_usage(set(), generic=True)
            return f"error: unexpected argument '{arg}' found\n\n{usage}\n\nFor more information, try '--help'.\n"
        if suggested:
            sug_long=LONG_OPTS[suggested][0].split()[0]  # --fix etc
            usage=build_usage(used, suggested=suggested, positional_filled=positional_filled)
            return f"error: unexpected argument '{arg}' found\n\n  tip: a similar argument exists: '{sug_long}'\n\n{usage}\n\nFor more information, try '--help'.\n"
        else:
            if is_short:
                usage=build_usage(set(), generic=True)
            else:
                usage=build_usage(used, positional_filled=positional_filled)
            return f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {original}'\n\n{usage}\n\nFor more information, try '--help'.\n"
    if kind=="unexpected_value":
        # for --help=foo
        flag=kw["flag"]  # key
        val=kw["value"]
        used=kw.get("used", set())
        usage=build_usage(used, suggested=flag)
        flag_long=LONG_OPTS[flag][0].split()[0]
        return f"error: unexpected value '{val}' for '{flag_long}' found; no more were expected\n\n{usage}\n\nFor more information, try '--help'.\n"
    if kind=="invalid_value":
        opt_disp=kw["opt_disp"]  # e.g. --fix <FIX>
        val=kw["value"]
        reason=kw.get("reason")  # for numeric
        possible=kw.get("possible")
        suggested=kw.get("suggested_value")
        s=f"error: invalid value '{val}' for '{opt_disp}'"
        if reason:
            s+=f": {reason}"
        s+="\n"
        if possible:
            s+="  [possible values: degree, radian, gradian]\n"
        if suggested:
            s+=f"\n  tip: a similar value exists: '{suggested}'\n"
        s+="\nFor more information, try '--help'.\n"
        return s
    if kind=="missing_value":
        opt_disp=kw["opt_disp"]
        possible=kw.get("possible")
        s=f"error: a value is required for '{opt_disp}' but none was supplied\n"
        if possible:
            s+="  [possible values: degree, radian, gradian]\n"
        s+="\nFor more information, try '--help'.\n"
        return s
    if kind=="multiple_times":
        opt_disp=kw["opt_disp"]
        usage=build_usage(set(), generic=True)
        return f"error: the argument '{opt_disp}' cannot be used multiple times\n\n{usage}\n\nFor more information, try '--help'.\n"
    return "error\n"

def colorize_cli_error(plain):
    # Apply clap tty styling heuristically
    # error: label bold red; quoted offending in first line yellow; tip: green; suggested quoted piece green; Usage heading etc; --help bold.
    text=plain
    # We'll do line-based transforms
    lines=text.split("\n")
    out=[]
    for line in lines:
        if line.startswith("error:"):
            # color error: and first quoted argument yellow
            # line: error: unexpected argument '--x' found
            # Replace first quoted token
            def repl_first(m):
                return f"'[33m{m.group(1)}[39m'"
            # color error:
            line = "[1m[31merror:[0m[39m[49m" + line[len("error:"):]
            # yellow first quoted string
            line, n = re.subn(r"'([^']+)'", lambda m: f"'[33m{m.group(1)}[39m'", line, count=1)
            out.append(line)
        elif line.strip().startswith("tip:"):
            # tip label green, and any quoted suggestion after use / exists is ... simpler: green whole quoted parts after colon except first?
            # Observed: tip: in green, '-- --unknown' green (without quotes), --fix etc? Let's green the tip label and quoted contents after "use"
            line=line.replace("tip:", "[32mtip:[39m", 1)
            # color quoted strings in this line green if they contain -- or are a candidate value? Observed for similar argument: '--fix' ? likely yellow? Need approximate: use green for second quoted when phrase "use"
            # We'll color last quoted string green if "use" in line, otherwise yellow?
            if "use '--" in line or "use '-- " in line:
                # color the argument inside use '' green
                # find all quotes; color last group
                parts=line.split("'")
                # parts index odd are quoted
                if len(parts)>=4:
                    # last quoted segment is 3rd? rebuild
                    # color the quoted segment that starts with --
                    for idx in range(1,len(parts),2):
                        if parts[idx].startswith("--"):
                            parts[idx]=f"[32m{parts[idx]}[39m"
                    line="'".join(parts)
            out.append(line)
        elif line.startswith("Usage:"):
            prog=prog_name()
            rest=line[len("Usage: "):]
            if rest.startswith(prog):
                rest=f"[1m{prog}[0m[39m[49m"+rest[len(prog):]
            out.append(f"[1;4mUsage:[0m[39m[49m " + rest)
        elif line.startswith("For more information"):
            line=line.replace("'--help'", "'[1m--help[0m[39m[49m'")
            out.append(line)
        else:
            out.append(line)
    return "\n".join(out)

