def parse_int_value(val, opt_disp, range_low, range_high):
    # Rust parse for unsigned? Original parse appears signed? -1 gave invalid digit, +2 works.
    # Python replicate Rust: parse::<u64? or i64?> messages: empty, invalid digit, too large
    # Determine type: values > 2^64-1 -> too large. Negative (with '-') gives invalid digit for unsigned, but + allowed.
    # Implementation: check empty
    if val=="":
        plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="cannot parse integer from empty string")
        emit_cli_error(plain)
    # Validate Rust unsigned parse: allowed leading '+' then digits only
    s=val
    neg=False
    body=s
    if body.startswith("+"):
        body=body[1:]
        if body=="":
            plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="invalid digit found in string")
            emit_cli_error(plain)
    if body.startswith("-"):
        # unsigned parse rejects '-'
        plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="invalid digit found in string")
        emit_cli_error(plain)
    if not body.isdigit() or body=="":
        # Rust also rejects spaces, underscores etc
        # But unicode digits? isdigit includes other; check ascii
        if not all('0'<=ch<='9' for ch in body):
            plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="invalid digit found in string")
            emit_cli_error(plain)
    # convert with overflow check u64 (or maybe usize 64)
    try:
        num=int(body)
    except:
        num=0
    # Leading + retained for display of value in range errors: original shows num without +? For +65, error says 65 is not in... (numeric). Range check message uses parsed number.
    # Check size: if number > 18446744073709551615 => too large.
    if num>18446744073709551615:
        plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="number too large to fit in target type")
        emit_cli_error(plain)
    if num < range_low or num > range_high:
        plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason=f"{num} is not in {range_low}..={range_high}")
        emit_cli_error(plain)
    return num

def parse_cli(argv):
    cfg_fix=10
    cfg_radix=10
    cfg_angle="degree"
    used=set()  # keys
    seen=set()
    input_val=None
    positional_filled=False
    end_of_options=False
    i=0
    while i < len(argv):
        arg=argv[i]
        if end_of_options:
            if input_val is not None:
                plain=format_cli_error("unexpected_arg", arg=arg, is_positional=True)
                emit_cli_error(plain)
            input_val=arg; positional_filled=True; i+=1; continue
        if arg=="--":
            end_of_options=True; i+=1; continue
        if arg.startswith("--") and len(arg)>2:
            # long
            if "=" in arg:
                name, val = arg[2:].split("=",1)
                has_eq=True
            else:
                name=arg[2:]; val=None; has_eq=False
            if name in LONG_OPTS:
