                    actual_val=val
                else:
                    # need next token not starting with -? Clap: if next is missing or starts with '-' etc it is missing.
                    if i+1>=len(argv) or (argv[i+1].startswith("-") and argv[i+1]!="-" and argv[i+1]!="--" ) or argv[i+1]=="--":
                        # Actually clap treats a leading '-' token as not a value if it looks like flag; also -- terminator
                        # Check if next exists but is exactly ??? Our earlier: -f --help is missing, -f -- is missing
                        plain=format_cli_error("missing_value", opt_disp=LONG_OPTS[key][0], possible=(key=="angle_unit"))
