            neg = True
        return -math.inf if neg else math.inf
    except ValueError:
        # 0 ** negative -> inf in C, negative ** fractional -> nan
        if a == 0.0:
            # sign depends
            neg = False
            if math.copysign(1.0, a) < 0 and float(b).is_integer() and int(b) % 2 != 0:
                neg = True
            return -math.inf if neg else math.inf
        return math.nan

def _ln(x):
    if math.isnan(x):
        return math.nan
    if x < 0:
        return math.nan
    if x == 0.0:
        return -math.inf
    return math.log(x)

def _log2(x):
    if math.isnan(x):
        return math.nan
    if x < 0:
        return math.nan
    if x == 0.0:
        return -math.inf
    return math.log2(x) if hasattr(math, "log2") else math.log(x, 2)

def _log10(x):
    if math.isnan(x):
        return math.nan
    if x < 0:
        return math.nan
    if x == 0.0:
        return -math.inf
    return math.log10(x)

def _sqrt(x):
    if x < 0:
        return math.nan
    return math.sqrt(x)  # sqrt(-0) -> -0.0 in python? math.sqrt(-0.0) == -0.0

def _asin(x):
    if x < -1.0 or x > 1.0:
        return math.nan
    return math.asin(x)
def _acos(x):
    if x < -1.0 or x > 1.0:
        return math.nan
    return math.acos(x)
def _sinh(x):
    try:
        return math.sinh(x)
    except OverflowError:
        return math.copysign(math.inf, x)
def _cosh(x):
    try:
        return math.cosh(x)
    except OverflowError:
        return math.inf
def _exp(x):
    try:
        return math.exp(x)
    except OverflowError:
        return math.inf
def _exp2(x):
    try:
        return math.pow(2.0, x) if False else _pow(2.0, x)
    except OverflowError:
        return math.inf

def _ceil(x):
    if not math.isfinite(x):
        return x
    r = float(math.ceil(x))
    if r == 0.0:
        return math.copysign(0.0, x)
    return r
def _floor(x):
    if not math.isfinite(x):
        return x
    r = float(math.floor(x))
    if r == 0.0:
        return math.copysign(0.0, x)
    return r
def _round(x):
    if not math.isfinite(x):
        return x
    # Rust round: half away from zero
    if x >= 0:
        r = float(math.floor(x + 0.5))
    else:
        r = float(math.ceil(x - 0.5))
    if r == 0.0:
        return math.copysign(0.0, x)
    return r

class Config:
    def __init__(self, fix=10, radix=10, angle_unit="degree"):
        self.fix = fix
        self.radix = radix
        self.angle_unit = angle_unit

    def convert_angle(self, x):
        if self.angle_unit == "radian":
            return x
        # degree and gradian both treated as degree (observed)
        return math.radians(x)

def make_functions(cfg):
    # returns dict name -> (arity, func taking list args)
    def trig(fn):
        return lambda x: fn(cfg.convert_angle(x))
    funcs = {}
    funcs["sin"] = (1, lambda a: math.sin(cfg.convert_angle(a[0])))
    funcs["cos"] = (1, lambda a: math.cos(cfg.convert_angle(a[0])))
    funcs["tan"] = (1, lambda a: math.tan(cfg.convert_angle(a[0])))
    funcs["csc"] = (1, lambda a: _div(1.0, math.sin(cfg.convert_angle(a[0]))))
    funcs["sec"] = (1, lambda a: _div(1.0, math.cos(cfg.convert_angle(a[0]))))
    funcs["cot"] = (1, lambda a: _div(1.0, math.tan(cfg.convert_angle(a[0]))))
    funcs["sinh"] = (1, lambda a: _sinh(a[0]))
    funcs["cosh"] = (1, lambda a: _cosh(a[0]))
    funcs["tanh"] = (1, lambda a: math.tanh(a[0]))
    funcs["asin"] = (1, lambda a: _asin(a[0]))
    funcs["acos"] = (1, lambda a: _acos(a[0]))
    funcs["atan"] = (1, lambda a: math.atan(a[0]))
    funcs["acsc"] = (1, lambda a: _asin(_div(1.0, a[0])))
    funcs["asec"] = (1, lambda a: _acos(_div(1.0, a[0])))
    funcs["acot"] = (1, lambda a: math.atan(_div(1.0, a[0])))
    funcs["ln"] = (1, lambda a: _ln(a[0]))
    funcs["log2"] = (1, lambda a: _log2(a[0]))
    funcs["log10"] = (1, lambda a: _log10(a[0]))
    funcs["sqrt"] = (1, lambda a: _sqrt(a[0]))
    funcs["ceil"] = (1, lambda a: _ceil(a[0]))
    funcs["floor"] = (1, lambda a: _floor(a[0]))
    funcs["abs"] = (1, lambda a: math.fabs(a[0]))
    funcs["exp"] = (1, lambda a: _exp(a[0]))
    funcs["exp2"] = (1, lambda a: _exp2(a[0]))
    funcs["rad"] = (1, lambda a: math.radians(a[0]))
    funcs["deg"] = (1, lambda a: math.degrees(a[0]))
    funcs["round"] = (1, lambda a: _round(a[0]))
    funcs["log"] = (2, lambda a: _div(_ln(a[0]), _ln(a[1])))
    funcs["nroot"] = (2, lambda a: _pow(a[0], _div(1.0, a[1])))
    return funcs

FUNCTION_NAMES = ["sin","cos","tan","csc","sec","cot","sinh","cosh","tanh","asin","acos","atan","acsc","asec","acot","ln","log2","log10","sqrt","ceil","floor","abs","exp","exp2","rad","deg","round","log","nroot"]
OPERATOR_NAMES = ["+","-","*","/","%","^","!"]

TOO_LARGE_MSG = None
def too_large_msg():
    global TOO_LARGE_MSG
    if TOO_LARGE_MSG is None:
        TOO_LARGE_MSG = "Error: to large to process! Max value: " + rust_display(1.7976931348623157e308)
    return TOO_LARGE_MSG

def rust_display(x):
    if math.isnan(x):
        return "NaN"
    if math.isinf(x):
        return "inf" if x > 0 else "-inf"
    if x == 0.0:
        return "-0" if math.copysign(1.0, x) < 0 else "0"
    s = repr(float(x))
    # convert scientific to plain using Decimal based on repr digits
    try:
        d = Decimal(s)
        out = format(d, 'f')
    except Exception:
        out = s
    if '.' in out:
        out = out.rstrip('0').rstrip('.')
        if out in ('-0', ''):
            out = '0' if not out.startswith('-') else '-0'
        if out == '-':
            out = '-0'
    return out

class CalcError(Exception):
    pass

def gen_help():
    consts = list(CONSTANTS.keys())
    funcs = list(FUNCTION_NAMES)
    ops = list(OPERATOR_NAMES)
    random.shuffle(consts)
    random.shuffle(funcs)
    random.shuffle(ops)
    lines = []
    lines.append("Constants")
    lines.append("".join(f"{c:>8}" for c in consts))
    lines.append("")
    lines.append("Functions")
    for i in range(0, len(funcs), 9):
        chunk = funcs[i:i+9]
        lines.append("".join(f"{f:>8}" for f in chunk))
    lines.append("")
    lines.append("Operators")
    lines.append(" ".join(ops))
    lines.append("")
    return "\n".join(lines) + "\n"

# ---------- Tokenizer ----------
# Token kinds: 'num','const','ans','func','op','lparen','rparen','comma','dummy'
class Token:
    __slots__=('kind','value')
    def __init__(self, kind, value=None):
        self.kind=kind
        self.value=value
    def __repr__(self):
        return f"Token({self.kind},{self.value!r})"

def tokenize(s, cfg):
    funcs = make_functions(cfg)
    tokens=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c.isdigit() or c=='.':
            if c=='.' and (i+1>=n or not s[i+1].isdigit()):
                tokens.append(Token('op','.'))
                i+=1
                continue
            j=i
            seen_dot=False
            while j<n and (s[j].isdigit() or (s[j]=='.' and not seen_dot)):
                if s[j]=='.':
                    seen_dot=True
                j+=1
            text=s[i:j]
            try:
                val=float(text)
            except:
                val=0.0
            tokens.append(Token('num', val))
            i=j
            continue
        if c=='_':
            tokens.append(Token('ans'))
            i+=1
            continue
        if c.isascii() and c.isalpha():
            j=i
            while j<n and s[j].isascii() and s[j].isalpha():
                j+=1
            word=s[i:j]
            nxt = s[j] if j<n else ''
            # underscore / dot errors take precedence for any word
            if nxt=='_':
                raise CalcError(f"Syntax Error: Unexpected character '{word}'")
            if nxt=='.':
                raise CalcError(f"Syntax Error: Unexpected character '{word}.'")
            if nxt.isdigit():
                # candidates for function names starting at i
                cand=[f for f in FUNCTION_NAMES if s.startswith(f, i)]
                if cand:
                    fname=max(cand, key=len)
                    after=i+len(fname)
                    after_ch = s[after] if after<n else ''
                    if after_ch=='(':
                        # treat as function; let main loop handle: set word and j
                        word=fname; j=after; nxt='('
                    elif after_ch=='':
                        # full function at EOF -> dummy
                        tokens.append(Token('dummy', fname))
                        i=after
                        continue
                    elif after_ch.isalpha():
                        # e.g. log10x : dummy for fname, then rest letters processed
                        tokens.append(Token('dummy', fname))
                        i=after
                        continue
                    else:
                        raise CalcError(f"Syntax Error: Function '{fname}' expected parentheses")
                if word in CONSTANTS:
                    tokens.append(Token('const', CONSTANTS[word]))
                    i=j
                    continue
                if word in funcs:
                    raise CalcError(f"Syntax Error: Function '{word}' expected parentheses")
                raise CalcError(f"Syntax Error: Unexpected character '{word}{nxt}'")
            if nxt=='(':
                if word in funcs:
                    tokens.append(Token('func', word))
                    i=j
                    continue
                else:
                    raise CalcError(f"Syntax Error: Unknown function '{word}'")
            # operators, ), comma, EOF, invalid chars
            if word in CONSTANTS:
                tokens.append(Token('const', CONSTANTS[word]))
                i=j
                continue
            # known function without parens or unknown: dummy
            tokens.append(Token('dummy', word))
            i=j
            continue
        if c=='*' and i+1<n and s[i+1]=='*':
            tokens.append(Token('op','^'))
            i+=2
            continue
        if c in '+-*/%^!':
            tokens.append(Token('op',c))
            i+=1
            continue
        if c=='(':
            tokens.append(Token('lparen'))
            i+=1
            continue
        if c==')':
            tokens.append(Token('rparen'))
            i+=1
            continue
        if c==',':
            tokens.append(Token('comma'))
            i+=1
            continue
        raise CalcError(f"Syntax Error: Unexpected token: '{c}'")
    return tokens

def insert_implicit(tokens):
    out=[]
    for idx, tok in enumerate(tokens):
        if out:
            prev=out[-1]
            # Actually need check prev original token = previous element before insertion (out[-1] could be inserted *, but inserted * kind op won't match)
            insert=False
            if prev.kind=='num' and tok.kind in ('lparen','func','const','ans'):
                insert=True
            elif prev.kind=='const' and tok.kind=='num':
                insert=True
            elif prev.kind=='rparen' and tok.kind=='lparen':
                insert=True
            if insert:
                out.append(Token('op','*'))
        out.append(tok)
    return out

PRECEDENCE={
    '+':2,'-':2,
    '*':3,'/':3,'%':3,
    '^':4,
    '!':5,
    'u-':6,'u+':6,
    'dummyop':6,
    '.':5,
}
RIGHT_ASSOC={'^','u-','u+'}
UNARY_OPS={'u-','u+','!','dummyop','.'}  # '.' treated as ??? will error in eval if used

def to_rpn(tokens):
    out=[]
    stack=[]
    # determine unary for +/-
    # We need prev token info based on tokens list (with implicit)
    for idx, tok in enumerate(tokens):
        if tok.kind in ('num','const','ans'):
            out.append(tok)
        elif tok.kind=='func':
            stack.append(tok)
        elif tok.kind=='dummy':
            # treat as binary operator token named dummyop
            # convert to op token
            op_tok=Token('op','dummyop')
            # push like operator
            cur_prec=PRECEDENCE['dummyop']
            while stack and stack[-1].kind=='op':
                top=stack[-1]
                top_prec=PRECEDENCE.get(top.value,0)
                if top_prec>cur_prec or (top_prec==cur_prec and 'dummyop' not in RIGHT_ASSOC):
                    out.append(stack.pop())
                else:
                    break
            stack.append(op_tok)
        elif tok.kind=='comma':
            found=False
            while stack:
                if stack[-1].kind=='lparen':
                    found=True
                    break
                out.append(stack.pop())
            if not found:
                raise CalcError("Syntax Error: Mismatched parentheses!")
        elif tok.kind=='op':
            sym=tok.value
            if sym in ('+','-'):
                # determine unary
                if idx==0:
                    is_unary=True
                else:
                    prev=tokens[idx-1]
                    if prev.kind=='lparen' or prev.kind=='func':
                        is_unary=True
                    elif prev.kind=='op' and prev.value!='!':
                        is_unary=True
                    else:
                        is_unary=False
                if is_unary:
                    sym='u+' if sym=='+' else 'u-'
                    tok=Token('op',sym)
            # operator handling
            cur_prec=PRECEDENCE.get(sym,0)
            is_right = sym in RIGHT_ASSOC
            while stack and stack[-1].kind=='op':
                top=stack[-1]
                top_prec=PRECEDENCE.get(top.value,0)
                if top_prec>cur_prec or (top_prec==cur_prec and not is_right):
                    out.append(stack.pop())
                else:
                    break
            stack.append(tok)
        elif tok.kind=='lparen':
            stack.append(tok)
        elif tok.kind=='rparen':
            found=False
            while stack:
                if stack[-1].kind=='lparen':
                    found=True
                    break
                out.append(stack.pop())
            if not found:
                raise CalcError("Syntax Error: Mismatched parentheses!")
            stack.pop() # lparen
            if stack and stack[-1].kind=='func':
                out.append(stack.pop())
        else:
            raise CalcError(f"Syntax Error: Unexpected token: '{tok.value}'")
    while stack:
        if stack[-1].kind=='lparen':
            raise CalcError("Syntax Error: Mismatched parentheses!")
        out.append(stack.pop())
    return out

def eval_rpn(rpn, cfg, prev_ans):
    funcs=make_functions(cfg)
    stack=[]
    for tok in rpn:
        if tok.kind=='num' or tok.kind=='const':
            stack.append(float(tok.value))
        elif tok.kind=='ans':
            if prev_ans is None:
                raise CalcError("Syntax Error: No previous answer!")
            stack.append(float(prev_ans))
        elif tok.kind=='func':
            name=tok.value
            arity, fn = funcs[name]
            if len(stack) < arity:
                raise CalcError(f"Parser Error: To few arguments for function, need {arity}")
            args=[]
            for _ in range(arity):
                args.append(stack.pop())
            args.reverse()
            result=fn(args)
            if not math.isfinite(result):
                raise CalcError("Domain Error: Out of bounds!")
            stack.append(result)
        elif tok.kind=='op':
            sym=tok.value
            if sym=='!':
                if len(stack)<1:
                    raise CalcError("Parser Error: Too many operators, too few operands")
                a=stack.pop()
                # factorial domain
                if a<0 or math.isnan(a) or math.isinf(a) or (math.isfinite(a) and a!=math.floor(a)):
                    raise CalcError("Domain Error: Out of bounds!")
                # iterative product
                res=1.0
                # a is integer-valued float
                n_int=int(a)
                for k in range(2, n_int+1):
                    res*=float(k)
                    if not math.isfinite(res):
                        # can break early; further multiplication stays inf
                        # but keep semantics: break
                        # However if we break, it's fine
                        pass
                if not math.isfinite(res):
                    raise CalcError(too_large_msg())
                stack.append(res)
            elif sym in ('u-','u+'):
                if len(stack)<1:
                    raise CalcError("Parser Error: Too many operators, too few operands")
                a=stack.pop()
                res=-a if sym=='u-' else a
                if not math.isfinite(res):
                    # unary plus on inf literal: res inf -> too large? check: if a is inf from literal, original would?
                    # For u+ / u-, treat as operator check
                    raise CalcError(too_large_msg())
                stack.append(res)
            elif sym=='dummyop' or sym=='.':
                raise CalcError("Parser Error: Too many operators, too few operands")
            else:
                # binary
                if len(stack)<2:
                    raise CalcError("Parser Error: Too many operators, too few operands")
                b=stack.pop(); a=stack.pop()
                if sym=='+':
                    res=a+b
                elif sym=='-':
                    res=a-b
                elif sym=='*':
                    res=a*b
                elif sym=='/':
                    if b==0.0:
                        raise CalcError("Math Error: Divide by zero error!")
                    res=_div(a,b)
                elif sym=='%':
                    # Rust % is fmod style
                    if b==0.0 or math.isnan(a) or math.isnan(b) or math.isinf(a):
                        res=math.nan
                    elif math.isinf(b):
                        res=a
                    else:
                        res=math.fmod(a,b)
                elif sym=='^':
                    res=_pow(a,b)
                else:
                    raise CalcError("Parser Error: Too many operators, too few operands")
                if not math.isfinite(res):
                    raise CalcError(too_large_msg())
                stack.append(res)
        else:
            raise CalcError("Parser Error: Too many operators, too few operands")
    if len(stack)!=1:
        raise CalcError("Parser Error: Too many operators, too few operands")
    return stack[0]

def evaluate(raw_input, cfg, prev_ans):
    # trim (unicode strip like Rust trim) and remove spaces
    s = raw_input.strip()
    s = s.replace(" ", "")
    if s=="":
        return 0.0
    if s=="help":
        raise CalcError(gen_help())
    # auto-balance parentheses
    open_c=s.count('(')
    close_c=s.count(')')
    if open_c>close_c:
        s=s+')'*(open_c-close_c)
    tokens=tokenize(s,cfg)
    tokens=insert_implicit(tokens)
    rpn=to_rpn(tokens)
    return eval_rpn(rpn,cfg,prev_ans)

# ---------- Formatting ----------
def add_commas_decimal(formatted):
    # formatted is fixed decimal string, may be inf/-inf/nan
    if formatted in ('inf','-inf','nan','NaN') or 'e' in formatted or 'E' in formatted:
        return formatted
    sign=''
    s=formatted
    if s.startswith('-'):
        sign='-'; s=s[1:]
    if '.' in s:
        intpart, frac = s.split('.',1)
        has_dot=True
    else:
        intpart, frac = s, ''
        has_dot=False
    # group intpart
    groups=[]
    while len(intpart)>3:
        groups.append(intpart[-3:])
        intpart=intpart[:-3]
    groups.append(intpart)
    grouped=','.join(reversed(groups))
    if has_dot:
        return f"{sign}{grouped}.{frac}"
    else:
        return f"{sign}{grouped}"

def format_result(num, cfg):
    fix=cfg.fix
    radix=cfg.radix
    # Rust fixed formatting
    if math.isnan(num):
        fixed="NaN"
    else:
        # python format for inf gives 'inf'
        fixed=format(float(num), f".{fix}f")
    if radix==10:
        return add_commas_decimal(fixed)
    # non-decimal
    if not math.isfinite(num):
        return fixed
    # parse fixed back
    try:
        rounded=float(fixed)
    except:
        rounded=float(num)
    if not math.isfinite(rounded):
        return fixed
    int_part=math.trunc(rounded)
    is_neg = rounded<0 or (rounded==0.0 and math.copysign(1.0, rounded)<0)
    # integer digits exact
    chars="0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if radix==1:
        # mimic original: hangs for >=1, else:
        if abs(int_part)>=1:
            # infinite loop as original
            while True:
                pass
        int_str="0"
        if is_neg:
            int_str="-0"
    else:
        n_abs=abs(int_part)  # int from float? int_part is int in py if trunc returns int; but for large float it's Python int converted exact
        # math.trunc for float returns int in python3, exact
        if n_abs==0:
            digits="0"
        else:
            digits=""
            nn=n_abs
            while nn>0:
                digits=chars[nn%radix]+digits
                nn//=radix
        int_str=("-" if is_neg else "")+digits
    padded=int_str.rjust(10)
    # group from right in 3s
    groups=[]
    pp=padded
    while len(pp)>3:
        groups.append(pp[-3:])
        pp=pp[:-3]
    groups.append(pp)
    grouped=','.join(reversed(groups))
    # fraction
    frac=abs(rounded - int_part) if False else abs(float(rounded) - float(int_part)) if abs(float(rounded))<1e308 else 0.0
    # For large numbers, fractional is 0; float subtraction fine.
    # Actually compute frac as abs(rounded) - abs(int_part) as float
    try:
        frac_val = abs(float(rounded) % 1.0) if math.isfinite(float(rounded)) else 0.0
        # Python % for negative follows divisor sign, abs handles; for -10.5, -10.5%1=0.5 good
        # But for large, %1 =0.0
    except Exception:
        frac_val=0.0
    if frac_val==0.0:
        frac_str="0"
    else:
        frac_str=""
        f=frac_val
        for _ in range(fix):
            f*=radix
            d=int(f)
            if d<0:
                d=0
            if d>=radix:
                d=radix-1
            frac_str+=chars[d]
            f-=d
            if f==0.0:
                break
        if frac_str=="":
            frac_str="0"
    return f"{grouped}.{frac_str}"

# ---------- CLI parsing (clap mimic) ----------
def prog_name():
    name=os.path.basename(sys.argv[0]) if sys.argv and sys.argv[0] else "executable"
    return name

HELP_TEMPLATE="""Calculator REPL similar to bc(1)

Usage: {prog} [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Optional expression string to run eva in command mode

Options:
  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]
  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]
  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]
  -h, --help                     Print help
  -V, --version                  Print version
"""

# styles for tty
def is_tty(stream):
    try:
        return stream.isatty()
    except:
        return False

def style_help_text(text, prog):
    # Apply clap-like styling when stdout is a tty: bold/underline headings, bold prog and flags
    # We reconstruct from plain text lines.
    # Use ANSI: headings "Usage:", "Arguments:", "Options:" bold+underline; prog bold following Usage; option flags bold
    out_lines=[]
    for line in text.split("\n"):
        if line.startswith("Usage: "):
            rest=line[len("Usage: "):]
            # rest starts with prog
            if rest.startswith(prog):
                rest = f"\x1b[1m{prog}\x1b[0m\x1b[39m\x1b[49m" + rest[len(prog):]
            out_lines.append(f"\x1b[1;4mUsage:\x1b[0m\x1b[39m\x1b[49m " + rest)
        elif line in ("Arguments:", "Options:"):
            out_lines.append(f"\x1b[1;4m{line}\x1b[0m\x1b[39m\x1b[49m")
        elif line.startswith("  -") or line.startswith("  [INPUT]"):
            # bold flag tokens
            # For option lines: bold -x and --xxx separately
            # Use regex
            def repl(m):
                return f"\x1b[1m{m.group(0)}\x1b[0m\x1b[39m\x1b[49m"
            line2=re.sub(r'(?<![\w-])-[a-zA-Z](?=(?:,|\s))|--[a-z_]+', repl, line)
            out_lines.append(line2)
        else:
            out_lines.append(line)
    return "\n".join(out_lines)

