def similarity(a, b):
    # Jaro-winkler like approximation used by clap/strsim. Implement Jaro-Winkler.
    # Return similarity score
    if a==b:
        return 1.0
    la, lb = len(a), len(b)
    if la==0 or lb==0:
        return 0.0
    # Jaro
    match_dist=max(la,lb)//2-1
    if match_dist<0:
        match_dist=0
    a_matches=[False]*la
    b_matches=[False]*lb
    matches=0
    for i in range(la):
        start=max(0, i-match_dist)
        end=min(i+match_dist+1, lb)
        for j in range(start, end):
            if b_matches[j]: continue
            if a[i]!=b[j]: continue
            a_matches[i]=True; b_matches[j]=True; matches+=1; break
    if matches==0:
        return 0.0
    k=0; trans=0
    for i in range(la):
        if not a_matches[i]: continue
        while not b_matches[k]: k+=1
        if a[i]!=b[k]: trans+=1
        k+=1
    trans//=2
    jaro=(matches/la + matches/lb + (matches-trans)/matches)/3
    # winkler prefix bonus up to 4
    prefix=0
    for i in range(min(4, min(la,lb))):
        if a[i]==b[i]: prefix+=1
        else: break
    return jaro + prefix*0.1*(1-jaro)

def suggest(word, candidates):
    best=None; best_score=0.0
    for cand in candidates:
        score=similarity(word, cand)
        # clap uses threshold 0.7? (?) based on tests: 'd' suggested radian (score?) ; 'g' suggested degree
        # Use jaro-winkler with threshold approx 0.7
        if score>best_score:
            best_score=score; best=cand
    if best is not None and best_score>0.7:  # approximate
        return best
    return None

