def parse_int_value(val, opt_disp, range_low, range_high):
    # Rust parse for unsigned? Original parse appears signed? -1 gave invalid digit, +2 works.
    # Python replicate Rust: parse::<u64? or i64?> messages: empty, invalid digit, too large
    # Determine type: values > 2^64-1 -> too large. Negative (with '-') gives invalid digit for unsigned, but + allowed.
    # Implementation: check empty
    if val=="":
        plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="cannot parse integer from empty string")
        emit_cli_error(plain)
    # Validate Rust unsigned parse: allowed leading '+' then digits only
    s=val
    neg=False
    body=s
    if body.startswith("+"):
        body=body[1:]
        if body=="":
            plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="invalid digit found in string")
            emit_cli_error(plain)
    if body.startswith("-"):
        # unsigned parse rejects '-'
        plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="invalid digit found in string")
        emit_cli_error(plain)
    if not body.isdigit() or body=="":
        # Rust also rejects spaces, underscores etc
        # But unicode digits? isdigit includes other; check ascii
        if not all('0'<=ch<='9' for ch in body):
            plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="invalid digit found in string")
            emit_cli_error(plain)
    # convert with overflow check u64 (or maybe usize 64)
    try:
        num=int(body)
    except:
        num=0
    # Leading + retained for display of value in range errors: original shows num without +? For +65, error says 65 is not in... (numeric). Range check message uses parsed number.
    # Check size: if number > 18446744073709551615 => too large.
    if num>18446744073709551615:
        plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason="number too large to fit in target type")
        emit_cli_error(plain)
    if num < range_low or num > range_high:
        plain=format_cli_error("invalid_value", opt_disp=opt_disp, value=val, reason=f"{num} is not in {range_low}..={range_high}")
        emit_cli_error(plain)
    return num

def parse_cli(argv):
    cfg_fix=10
    cfg_radix=10
    cfg_angle="degree"
    used=set()  # keys
    seen=set()
    input_val=None
    positional_filled=False
    end_of_options=False
    i=0
    while i < len(argv):
        arg=argv[i]
        if end_of_options:
            if input_val is not None:
                plain=format_cli_error("unexpected_arg", arg=arg, is_positional=True)
                emit_cli_error(plain)
            input_val=arg; positional_filled=True; i+=1; continue
        if arg=="--":
            end_of_options=True; i+=1; continue
        if arg.startswith("--") and len(arg)>2:
            # long
            if "=" in arg:
                name, val = arg[2:].split("=",1)
                has_eq=True
            else:
                name=arg[2:]; val=None; has_eq=False
            if name in LONG_OPTS:
                key=name
                if key in ("help","version"):
                    if has_eq:
                        # unexpected value
                        plain=format_cli_error("unexpected_value", flag=key, value=val, used=set(used))
                        emit_cli_error(plain)
                    if key=="help":
                        emit_help()
                    else:
                        emit_version()
                # value option
                if key in seen:
                    plain=format_cli_error("multiple_times", opt_disp=LONG_OPTS[key][0])
                    emit_cli_error(plain)
                if has_eq:
                    if val=="" and key=="angle_unit":
                        # --angle_unit= gives missing value not invalid
                        plain=format_cli_error("missing_value", opt_disp=LONG_OPTS[key][0], possible=True)
                        emit_cli_error(plain)
                    actual_val=val
                else:
                    # need next token not starting with -? Clap: if next is missing or starts with '-' etc it is missing.
                    if i+1>=len(argv) or (argv[i+1].startswith("-") and argv[i+1]!="-" and argv[i+1]!="--" ) or argv[i+1]=="--":
                        # Actually clap treats a leading '-' token as not a value if it looks like flag; also -- terminator
                        # Check if next exists but is exactly ??? Our earlier: -f --help is missing, -f -- is missing
                        plain=format_cli_error("missing_value", opt_disp=LONG_OPTS[key][0], possible=(key=="angle_unit"))
                        emit_cli_error(plain)
                    # Also if next token starts with '-' and is something like -1, clap considered it unexpected argument earlier? Wait -f -1 case: original gave unexpected argument '-1' not missing. Hmm.
                    # Our above branch would give missing; need replicate: if next token starts with '-' and length>1, clap parsing: it checks if it's a known flag? For -1 unknown, error unexpected argument '-1' would happen after? Actually test: ["-f","-1","1/3"] gave unexpected '-1'. So if next token looks like an argument, missing? Wait output was unexpected, not missing.
                    # We'll handle that in actual flow below before emitting missing for unknown hyphen tokens.
                    actual_val=argv[i+1]; i+=1
                # validate
                if key=="fix":
                    cfg_fix=parse_int_value(actual_val, LONG_OPTS[key][0], 1, 64)
                elif key=="base":
                    cfg_radix=parse_int_value(actual_val, LONG_OPTS[key][0], 1, 36)
                elif key=="angle_unit":
                    if actual_val not in ("degree","radian","gradian"):
                        sug=suggest(actual_val, ["degree","radian","gradian"])
                        plain=format_cli_error("invalid_value", opt_disp=LONG_OPTS[key][0], value=actual_val, possible=True, suggested_value=sug)
                        emit_cli_error(plain)
                    cfg_angle=actual_val
                seen.add(key); used.add(key)
                i+=1; continue
            else:
                # unknown long
                sug_name=suggest(name, list(LONG_OPTS.keys()))
                sug_key=sug_name if sug_name else None
                arg_disp=f"--{name}"
                plain=format_cli_error("unexpected_arg", arg=arg_disp, original=arg_disp, suggested=sug_key, used=set(used), positional_filled=positional_filled)
                emit_cli_error(plain)
        elif arg.startswith("-") and arg!="-" :
            # short cluster
            # iterate characters
            j=1
            consumed_next_for_value=False
            while j < len(arg):
                ch=arg[j]
                if ch not in SHORT_TO_LONG:
                    disp=f"-{ch}"
                    plain=format_cli_error("unexpected_arg", arg=disp, original=disp, is_short=True, used=set(used), positional_filled=positional_filled)
                    emit_cli_error(plain)
                key=SHORT_TO_LONG[ch]
                if key in ("help","version"):
                    if key=="help":
                        emit_help()
                    else:
                        emit_version()
                # value option: rest of arg is its value (strip leading = if present)
                if key in seen:
                    plain=format_cli_error("multiple_times", opt_disp=LONG_OPTS[key][0])
                    emit_cli_error(plain)
                rest=arg[j+1:]
                if rest!="":
                    if rest.startswith("="):
                        rest=rest[1:]
                    actual_val=rest
                else:
                    # need next argv
                    if i+1>=len(argv):
                        plain=format_cli_error("missing_value", opt_disp=LONG_OPTS[key][0], possible=(key=="angle_unit"))
                        emit_cli_error(plain)
                    nxt=argv[i+1]
                    if nxt.startswith("-") and nxt!="-":
                        # decide between missing vs unexpected: if nxt is a known flag or --help etc, missing observed for --help/-h/--
                        # if nxt is unknown like -1/-x, clap reports unexpected argument for that token (not missing). Our handling: check
                        # Known tokens handling:
                        # Simplify: if nxt == "--" or nxt[1] in known shorts or nxt starts with a known long, then missing.
                        # Else emit unexpected for nxt (with short logic if applicable)
                        # Determine:
                        is_known=False
                        if nxt=="--":
                            is_known=True
                        elif nxt.startswith("--"):
                            lname=nxt[2:].split("=",1)[0]
                            if lname in LONG_OPTS:
                                is_known=True
                        else:
                            if len(nxt)>=2 and nxt[1] in SHORT_TO_LONG:
                                is_known=True
                        if is_known:
                            plain=format_cli_error("missing_value", opt_disp=LONG_OPTS[key][0], possible=(key=="angle_unit"))
                            emit_cli_error(plain)
                        else:
                            # unexpected argument for nxt token
                            # For long unknown, format with suggestion logic; for short, -firstchar
                            if nxt.startswith("--"):
                                lname=nxt[2:].split("=",1)[0]
                                sug_name=suggest(lname, list(LONG_OPTS.keys()))
                                plain=format_cli_error("unexpected_arg", arg=f"--{lname}", original=f"--{lname}", suggested=sug_name, used=set(used), positional_filled=positional_filled)
                                emit_cli_error(plain)
                            else:
                                disp=f"-{nxt[1]}" if len(nxt)>=2 else nxt
                                plain=format_cli_error("unexpected_arg", arg=disp, original=disp, is_short=True, used=set(used), positional_filled=positional_filled)
                                emit_cli_error(plain)
                    actual_val=nxt; consumed_next_for_value=True
                # validate
                if key=="fix":
                    cfg_fix=parse_int_value(actual_val, LONG_OPTS[key][0], 1, 64)
                elif key=="base":
                    cfg_radix=parse_int_value(actual_val, LONG_OPTS[key][0], 1, 36)
                elif key=="angle_unit":
                    if actual_val not in ("degree","radian","gradian"):
                        sug=suggest(actual_val, ["degree","radian","gradian"])
                        plain=format_cli_error("invalid_value", opt_disp=LONG_OPTS[key][0], value=actual_val, possible=True, suggested_value=sug)
                        emit_cli_error(plain)
                    cfg_angle=actual_val
                seen.add(key); used.add(key)
                break  # rest consumed as value
            if consumed_next_for_value:
                i+=1
            i+=1; continue
        else:
            # positional
            if input_val is not None:
                plain=format_cli_error("unexpected_arg", arg=arg, is_positional=True)
                emit_cli_error(plain)
            input_val=arg; positional_filled=True; i+=1; continue
    cfg=Config(fix=cfg_fix, radix=cfg_radix, angle_unit=cfg_angle)
    return cfg, input_val

