    # Determine roles of '!' tokens and special-case prefix factorial.
    # A prefix '!' followed by a primary discards that primary and yields 1
    # (observed original behaviour, e.g. !5 == 1, 3+!5 == 4).
    # In a run of prefix '!' tokens, only the last one is transformed this way;
    # earlier ones remain as ordinary '!' operators (e.g. 3+!!2 == 3!+1).
    roles = {}
    for idx, tok in enumerate(tokens):
        if tok.kind == 'op' and tok.value == '!':
            if idx == 0:
                roles[idx] = 'prefix'
            else:
                prev = tokens[idx-1]
                if prev.kind in ('num', 'const', 'ans', 'rparen'):
                    roles[idx] = 'postfix'
                elif prev.kind == 'op' and prev.value == '!':
                    roles[idx] = roles.get(idx-1, 'postfix')
                elif prev.kind == 'op':
                    roles[idx] = 'prefix'
                elif prev.kind in ('lparen', 'comma', 'func', 'dummy', 'barefunc'):
                    roles[idx] = 'prefix'
                else:
                    roles[idx] = 'postfix'
    out = []
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        if tok.kind == 'op' and tok.value == '!' and roles.get(i) == 'prefix' and i + 1 < len(tokens):
            nxt = tokens[i+1]
            if nxt.kind in ('num', 'const', 'ans', 'dummy'):
                out.append(Token('num', 1.0))
                i += 2
                continue
            if nxt.kind == 'func':
                # consume function and its balanced parenthesised group
                j = i + 2
                if j < len(tokens) and tokens[j].kind == 'lparen':
                    depth = 0
                    while j < len(tokens):
                        if tokens[j].kind == 'lparen':
                            depth += 1
                        elif tokens[j].kind == 'rparen':
                            depth -= 1
                            if depth == 0:
                                j += 1
                                break
                        j += 1
                    out.append(Token('num', 1.0))
                    i = j
                    continue
                else:
                    out.append(Token('num', 1.0))
                    i += 2
                    continue
            if nxt.kind == 'lparen':
                j = i + 1
                depth = 0
                while j < len(tokens):
