def run(b, setup):
    home="/tmp/histerr"
    if os.path.exists(home): shutil.rmtree(home)
    os.makedirs(home)
    setup(home)
    env=dict(os.environ); env["HOME"]=home
    p=subprocess.run([b], input="1+1\n", capture_output=True, text=True, env=env)
    return p.stdout,p.stderr,p.returncode
