binpath=sys.argv[1]; home=sys.argv[2]; actions=sys.argv[3].split("|")
os.makedirs(home, exist_ok=True)
env=dict(os.environ); env["HOME"]=home
pid, fd = pty.fork()
if pid==0: os.execve(binpath,[binpath],env)
def read_all(t=0.4):
    d=b""; end=time.time()+t
    while time.time()<end:
        r,_,_=select.select([fd],[],[],0.05)
        if fd in r:
            try: c=os.read(fd,4096)
            except: break
            if not c: break
            d+=c
    return d
print("init",repr(read_all(0.6)))
for s in actions:
    mp={"ENTER":b"\r","CTRLC":b"\x03","CTRLD":b"\x04","CTRLU":b"\x15","UP":b"\x1b[A","DOWN":b"\x1b[B","LEFT":b"\x1b[D","RIGHT":b"\x1b[C","BS":b"\x7f","CTRLA":b"\x01","CTRLE":b"\x05","CTRLK":b"\x0b","CTRLW":b"\x17"}
    os.write(fd, mp.get(s,s.encode()))
    print(s, repr(read_all(0.4)))
try: os.kill(pid,9)
except: pass
